import{_ as a,o as e,c as t,a2 as o}from"./chunks/framework.CHeM0PsO.js";const d=JSON.parse('{"title":"AI 与手术机器人晨报｜2026-08-14","description":"","frontmatter":{},"headers":[],"relativePath":"2026-08-14-AI与手术机器人晨报.md","filePath":"2026-08-14-AI与手术机器人晨报.md","lastUpdated":1786770226000}'),i={name:"2026-08-14-AI与手术机器人晨报.md"};function n(s,r,l,h,g,p){return e(),t("div",null,[...r[0]||(r[0]=[o('<h1 id="ai-与手术机器人晨报-2026-08-14" tabindex="-1">AI 与手术机器人晨报｜2026-08-14 <a class="header-anchor" href="#ai-与手术机器人晨报-2026-08-14" aria-label="Permalink to &quot;AI 与手术机器人晨报｜2026-08-14&quot;">​</a></h1><blockquote><p><strong>主题：推理可以慢，安全必须快——为不同时间尺度分配不同智能</strong></p><p>信息窗口：2026-08-11 至 2026-08-14（北京时间）。本期优先核对 arXiv 论文原文、HTML 全文、作者项目页以及 FDA/厂商官方页面，只保留与 AI Native、机器人强化学习、实时控制和远程手术直接相关的工作。以下论文均为 8 月 11–12 日提交的 v1（RIFT 已更新至 8 月 13 日 v2）预印本；除文中明确写出的真实机器人或在体实验外，不应外推为临床证据。最近 72 小时没有足够高价值的新手术机器人监管、临床或产品里程碑，因此本期刻意缩短该部分。<a href="https://arxiv.org/list/cs.AI/new" target="_blank" rel="noreferrer">arXiv cs.AI 最新列表</a>｜<a href="https://arxiv.org/list/cs.RO/new" target="_blank" rel="noreferrer">arXiv cs.RO 最新列表</a></p></blockquote><hr><h2 id="今日摘要" tabindex="-1">今日摘要 <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;今日摘要&quot;">​</a></h2><ol><li><strong>机器人智能正在重新划分“思考”和“动作”的接口。</strong> G0.5 把任务分解、目标定位和动作 token 放回同一自回归流；RIFT 则反向证明，世界动作模型不必在每次控制时完整生成未来视频，只需在一次前向中形成可供动作读取的未来表征。</li><li><strong>预训练不是自主学习的替代品，而是把搜索范围缩到可学习区域。</strong> MiDAS 用一条示教把 VLA 锚定到任务，再冻结主干、用在线残差 RL 学纠偏；真实双臂任务中，作者报告 5–6 小时、每任务 350 条自主轨迹后，较难任务成功率从 27% 提到 80%。</li><li><strong>医疗机器人真正需要的是多时间尺度闭环。</strong> 机器人超声用 RGB-D 局部表面模型和任务空间控制维持非垂直探头角度；触觉系统工作则用 Koopman 提升空间分析非线性虚拟环境的闭环稳定性。两者都提示：高层语义模型不能替代贴近传感器和执行器的局部动力学闭环。</li><li><strong>安全约束应位于最终命令边界。</strong> 一项自动驾驶研究把无学习的神经符号 guard 接到控制命令之前，按显式规则把危险命令替换为最近的安全动作。它不是手术机器人证据，但与远程手术患者侧硬约束的结构高度同构。</li><li><strong>交叉结论：不要让一种模型承担所有时间尺度。</strong> 慢环负责语义、任务和候选未来；中环负责适配、价值与状态重评估；快环负责伺服、触觉、RCM、速度/力边界和急停。系统可靠性来自接口和降级路径，而不是某一层“更聪明”。</li></ol><hr><h2 id="ai-前沿" tabindex="-1">AI 前沿 <a class="header-anchor" href="#ai-前沿" aria-label="Permalink to &quot;AI 前沿&quot;">​</a></h2><h3 id="_1-g0-5-让-vlm-不只理解动作-而是直接生成动作" tabindex="-1">1. G0.5：让 VLM 不只理解动作，而是直接生成动作 <a class="header-anchor" href="#_1-g0-5-让-vlm-不只理解动作-而是直接生成动作" aria-label="Permalink to &quot;1. G0.5：让 VLM 不只理解动作，而是直接生成动作&quot;">​</a></h3><p><strong>事实。</strong> 当前主流 VLA 常把预训练 VLM 当上下文编码器，再由独立 flow-matching action expert 输出连续动作。G0.5 改回单一自回归 decoder：图像、语言、任务分解、目标框、轨迹提示和动作码共享词表与 next-token 目标。为压缩自回归控制成本，模型用跨 embodiment 的可学习 ActionCodec，把不同自由度、频率和形态的连续动作映射到共享离散码；不活动的身体部件不生成 token。模型还在视觉编码器内保留有界的多秒历史，而不是无限堆叠历史 token。<a href="https://arxiv.org/abs/2608.11739" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2608.11739v1" target="_blank" rel="noreferrer">HTML 全文</a>｜<a href="https://opengalaxea.github.io/G05/" target="_blank" rel="noreferrer">作者项目页</a></p><p><strong>作者结果。</strong> G0.5 覆盖 14 种 embodiment，并在多类基准上报告 98.9% LIBERO、93.3% RoboTwin 2.0、87.3% SimplerEnv-Bridge；在排除目标环境和实物实例的 DROID 后训练中报告 82.5% 零样本迁移。在 R1-Lite/R1-Pro 真实机器人微调任务上，作者给出的汇总结果为 76.7%，对比 π0.5 的 53.3% 和 GR00T-N1.7 的 24.4%。</p><p><strong>边界。</strong> 论文关于“prompt 可直接改变动作粒度、空间提示和动词行为”的证据主要来自两个长时程任务的定性 probe，作者明确称其为早期线索而非系统量化结论。基准平均分也不能证明在软组织接触、器械约束或网络异常下可靠；把 CoT 与动作放在同一流中增强了耦合，同时也扩大了语言输入直接影响执行分布的攻击面。</p><p><strong>推断。</strong> 对 AI Native 而言，G0.5 的价值不是“所有模块都该合并”，而是提示：当推理结果要真正改变动作时，推理—动作接口必须在训练目标里被联合验证。对手术机器人，较合理的迁移方式是让统一模型负责技能选择、阶段识别、目标/禁区表达和候选动作，不直接越过患者侧安全核；尤其不能把自然语言 prompt 当作速度、力或 RCM 约束的权威来源。</p><h3 id="_2-rift-保留-未来-删掉实时回路里的视频-rollout" tabindex="-1">2. RIFT：保留“未来”，删掉实时回路里的视频 rollout <a class="header-anchor" href="#_2-rift-保留-未来-删掉实时回路里的视频-rollout" aria-label="Permalink to &quot;2. RIFT：保留“未来”，删掉实时回路里的视频 rollout&quot;">​</a></h3><p><strong>事实。</strong> 世界动作模型通常先迭代生成未来视频，再让动作 expert 读取未来 token；未来有用，但生成过程很慢。RIFT 先对四类 WAM 的 future-position K/V cache 做成对闭环干预：删掉或错位未来值会显著改变轨迹，说明动作确实使用未来内容；但对 Joint 和 Cosmos-2，反复复用一次最终干净的 K/V cache，仍保持 97.9%–98.2% 成功率。于是作者用 learned anticipation tokens 在一次 backbone pass 中直接写出完整未来 cache，不再在部署时生成视频。<a href="https://arxiv.org/abs/2608.11521" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2608.11521v2" target="_blank" rel="noreferrer">HTML 全文</a></p><p><strong>作者结果。</strong> 在相同 Wan2.2-5B backbone、训练数据和 20k 步预算下，RIFT 在 LIBERO 达到 98.8%，action chunk 延迟为 247.9 ms；rollout-based 对照为 780.2–2270.3 ms，作者据此报告 68.2%–89.1% 延迟下降。LIBERO-Plus 10,030 个 OOD 变体中，RIFT 为 81.1%；RoboTwin 2.0 clean/randomized 为 92.9%/92.6%。</p><p><strong>边界。</strong> 全部闭环结果都来自仿真，延迟只在单张 A800、各方法原生 denoising 设置下测得；论文明确把真实机器人列为未来工作。247.9 ms 仍不是远程手术内环可接受的控制周期，且可选 uncertainty readout 未计入主延迟。作者也提醒，两种 future estimator 可能一致地预测错误。</p><p><strong>推断。</strong> 这对远程手术最重要的不是具体加速百分比，而是“生产未来”和“消费未来”可以解耦。可在边缘/患者侧提前生成短窗风险表征，由更快的动作层重复读取；视频解码只用于审计和人机界面，不应成为每个控制周期的前置依赖。任何落地实验必须报告端到端尾延迟、陈旧度和降级条件，而不是只报 GPU kernel 平均值。</p><hr><h2 id="手术机器人与远程手术" tabindex="-1">手术机器人与远程手术 <a class="header-anchor" href="#手术机器人与远程手术" aria-label="Permalink to &quot;手术机器人与远程手术&quot;">​</a></h2><h3 id="_1-midas-一条示教指定方向-在线残差-rl-补可靠性" tabindex="-1">1. MiDAS：一条示教指定方向，在线残差 RL 补可靠性 <a class="header-anchor" href="#_1-midas-一条示教指定方向-在线残差-rl-补可靠性" aria-label="Permalink to &quot;1. MiDAS：一条示教指定方向，在线残差 RL 补可靠性&quot;">​</a></h3><p><strong>事实。</strong> MiDAS 面向 minimal-data adaptation：先用一条或少量成功示教对预训练 π0.5 做行为克隆，使策略能到达任务相关区域；再冻结 VLA，通过轻量 residual actor-critic 和稀疏奖励在线学习。残差策略读取基础动作 proposal，但直接输出编辑后的动作，而非只在固定小邻域内加 offset；真实机器人阶段另以每关节 0.2 rad trust region 限制偏离。<a href="https://arxiv.org/abs/2608.11363" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2608.11363v1" target="_blank" rel="noreferrer">HTML 全文</a>｜<a href="https://minimal-data-adaptation.github.io/" target="_blank" rel="noreferrer">作者项目页</a></p><p><strong>作者结果。</strong> 单示教下，MiDAS 在 LIBERO-Long 十个任务平均 91.2%，行为克隆为 33.5%；RoboCasa 报告的三个可解任务平均 89.3%，另一个 1100-step 洗碗机任务所有方法均为 0%。真实 YAM 双臂平台只做两个 pick-and-place 任务、每格 15 次评估：较易任务从 40% 到 67%，较难任务从 27% 到 80%；训练耗时 5–6 小时，每任务收集 350 条轨迹。</p><p><strong>边界。</strong> 作者明确指出：在线 RL 主要把一个已示范行为扩展到邻近状态，不能自动发现示教支持之外的新行为模式；对象交换会让策略从强 in-distribution 结果跌到 0%。真实实验规模小、任务偏日常抓放，并依赖自动 reset 与可直接判定的稀疏成功信号，这些条件在手术中都更昂贵、更危险。</p><p><strong>推断。</strong> 手术机器人 RL 的最小可行路线不是让临床设备“自由探索”，而是：专家示教定义一个窄安全管道；仿真、台架和离体组织中的 residual RL 只在管道内学习纠偏；患者侧部署时 residual 输出再经过独立硬约束。探索分布扩大必须按阶段课程进行，并用 failure coverage 而非总 episode 数作为是否晋级的依据。</p><h3 id="_2-机器人超声-局部几何模型服务于实时姿态闭环" tabindex="-1">2. 机器人超声：局部几何模型服务于实时姿态闭环 <a class="header-anchor" href="#_2-机器人超声-局部几何模型服务于实时姿态闭环" aria-label="Permalink to &quot;2. 机器人超声：局部几何模型服务于实时姿态闭环&quot;">​</a></h3><p><strong>事实。</strong> 该工作针对超声探头只保持表面法向、无法获得心脏等非垂直诊断视角的问题，将 RGB-D 多视角点云融合为局部二次曲面，并在任务空间编码相对法向的目标方向，使探头在人体表面运动时维持任意倾角。实验包含平面跟踪、phantom 目标角恢复，以及专家选定视角的在体跟踪。<a href="https://arxiv.org/abs/2608.11409" target="_blank" rel="noreferrer">论文原文</a></p><p><strong>作者结果。</strong> 论文报告平均角度跟踪误差 1.06 ± 0.66°，可恢复相对表面法向 44.39 ± 2.59° 的非垂直倾角，并在 phantom 和 in-vivo 实验中获得目标心腔视图。</p><p><strong>边界。</strong> 这是机器人超声而非腔镜手术；摘要未提供大样本受试者统计、长时间稳定性、接触力/呼吸运动边界或远程链路条件。结果证明的是局部表面估计与姿态控制的可行性，不是诊断效果或远程临床安全性。</p><p><strong>推断。</strong> 对远程手术而言，它给出一个比“端到端大模型控制全部器械”更可信的结构：高层指定期望视角/解剖目标，患者侧局部模型把目标转为表面相对约束，实时控制器持续闭合误差。把状态表达成“相对组织表面/RCM/禁区”的任务坐标，比跨网络传绝对位姿更能抵抗患者移动和模型陈旧。</p><h3 id="_3-触觉稳定性与命令口-safety-guard-快环必须可分析、可拦截" tabindex="-1">3. 触觉稳定性与命令口 safety guard：快环必须可分析、可拦截 <a class="header-anchor" href="#_3-触觉稳定性与命令口-safety-guard-快环必须可分析、可拦截" aria-label="Permalink to &quot;3. 触觉稳定性与命令口 safety guard：快环必须可分析、可拦截&quot;">​</a></h3><p><strong>事实。</strong> 一项触觉系统研究用 Koopman operator 在升维空间表示 Duffing 非线性虚拟环境，以线性组合表达非线性，并据此进行闭环稳定性分析；作者报告其比传统 passivity-based 分析更不保守，并在仿真、实验和多用户研究中验证。<a href="https://arxiv.org/abs/2608.11461" target="_blank" rel="noreferrer">论文原文</a></p><p>另一项自动驾驶工作把不含学习组件的神经符号 guard 接在端到端 agent 的最终命令接口：按显式规则检查控制命令，必要时替换为最近安全动作，并记录触发规则。作者在 Fail2Drive/Bench2Drive 上报告成功率提高 15%、安全关键碰撞最多下降 53%，且原 Driving Score 不变。<a href="https://arxiv.org/abs/2608.11451" target="_blank" rel="noreferrer">论文原文</a></p><p><strong>来源观点。</strong> 两篇工作都主张把安全性放在可分析的模型或可执行的最终接口，而不是仅依赖黑盒策略的平均表现。</p><p><strong>推断。</strong> 这两项都不是手术机器人临床证据，但可交叉支持同一工程原则：患者侧快环应由可证明/可测试的动力学、力反馈稳定性和动作投影组成；任何 VLA、world model 或在线 RL 输出都必须先过速度、加速度、力、RCM、工作空间、器械互锁和控制权状态检查。guard 的每次改写还应作为高价值训练数据回流，而不是静默吞掉策略错误。</p><h3 id="_4-产品、临床与监管-本窗口没有新的高价值里程碑" tabindex="-1">4. 产品、临床与监管：本窗口没有新的高价值里程碑 <a class="header-anchor" href="#_4-产品、临床与监管-本窗口没有新的高价值里程碑" aria-label="Permalink to &quot;4. 产品、临床与监管：本窗口没有新的高价值里程碑&quot;">​</a></h3><p>截至 2026-08-14 早间，FDA CDRH/De Novo 官方列表未显示最近 72 小时新的手术机器人决定；Johnson &amp; Johnson 医疗科技列表中最近的重要手术机器人事项仍是 7 月 22 日 OTTAVA De Novo authorization；Intuitive 官方 Newsroom 最近公开内容也未出现新的远程手术临床实施。FDA 对现有 robotically-assisted surgical device 的公开说明仍强调此类系统由医生直接控制，不应把当前 RAS 与自主手术混为一谈。本期不以会议议程、市场稿或旧授权填充“今日新闻”。<a href="https://www.fda.gov/medical-devices/surgery-devices/computer-assisted-surgical-systems" target="_blank" rel="noreferrer">FDA 计算机辅助手术系统说明</a>｜<a href="https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/denovo.cfm" target="_blank" rel="noreferrer">FDA De Novo 数据库</a>｜<a href="https://www.jnj.com/media-center/press-releases/johnson-johnson-receives-fda-market-authorization-in-the-u-s-for-its-ottava-robotic-surgical-system" target="_blank" rel="noreferrer">J&amp;J OTTAVA 官方公告</a>｜<a href="https://www.intuitive.com/en-us/about-us/newsroom" target="_blank" rel="noreferrer">Intuitive Newsroom</a></p><hr><h2 id="论文-产品-监管动态" tabindex="-1">论文 / 产品 / 监管动态 <a class="header-anchor" href="#论文-产品-监管动态" aria-label="Permalink to &quot;论文 / 产品 / 监管动态&quot;">​</a></h2><h3 id="论文" tabindex="-1">论文 <a class="header-anchor" href="#论文" aria-label="Permalink to &quot;论文&quot;">​</a></h3><ul><li><strong>统一 VLA：</strong> G0.5 试图用共享自回归流把语言推理、视觉记忆与跨机器人动作码直接接起来；prompt steering 仍主要是定性证据。</li><li><strong>低延迟 world action model：</strong> RIFT 以一次 future-cache prefill 替代迭代视频 rollout，在仿真中保留成功率并显著降低 action-chunk 延迟。</li><li><strong>机器人强化学习：</strong> MiDAS 把“单示教”定位为探索锚点而非完整监督，在线 residual RL 负责邻域内纠偏；新行为模式和长时程任务仍明显受限。</li><li><strong>医疗机器人控制：</strong> 机器人超声用表面相对坐标闭合非垂直姿态，提供了高层目标与患者侧局部控制分层的实证样例。</li><li><strong>快环安全：</strong> Koopman 触觉模型与命令口 safety guard 分别从稳定性分析和动作投影支持“安全约束贴近执行器”的设计。</li></ul><h3 id="产品与监管" tabindex="-1">产品与监管 <a class="header-anchor" href="#产品与监管" aria-label="Permalink to &quot;产品与监管&quot;">​</a></h3><p>最近 72 小时没有足够高价值的新手术机器人产品、远程手术临床或监管进展；本期刻意留白。</p><hr><h2 id="对-nathan-当前项目的启示" tabindex="-1">对 Nathan 当前项目的启示 <a class="header-anchor" href="#对-nathan-当前项目的启示" aria-label="Permalink to &quot;对 Nathan 当前项目的启示&quot;">​</a></h2><h3 id="_1-为远程手术画一张-三环时序图-再讨论模型" tabindex="-1">1. 为远程手术画一张“三环时序图”，再讨论模型 <a class="header-anchor" href="#_1-为远程手术画一张-三环时序图-再讨论模型" aria-label="Permalink to &quot;1. 为远程手术画一张“三环时序图”，再讨论模型&quot;">​</a></h3><ul><li><strong>慢环（0.5–5 s）：</strong> 术式阶段、目标/禁区、技能选择、未来候选与人工确认。</li><li><strong>中环（50–500 ms）：</strong> 状态重评估、短窗未来表征、动作 chunk、残差纠偏、网络质量与控制权切换。</li><li><strong>快环（0.5–10 ms）：</strong> 位置/速度/力伺服、RCM、器械互锁、患者侧 guard 与急停。</li></ul><p><strong>完成标准：</strong> 每个算法模块都标明输入时间戳、deadline、最大陈旧度、超时行为和降级所有者；任何慢环/中环 miss deadline 时，快环仍能维持安全状态，而不是等待模型返回。</p><h3 id="_2-建一个-future-representation-contract-不要直接上视频生成" tabindex="-1">2. 建一个 “future representation contract”，不要直接上视频生成 <a class="header-anchor" href="#_2-建一个-future-representation-contract-不要直接上视频生成" aria-label="Permalink to &quot;2. 建一个 “future representation contract”，不要直接上视频生成&quot;">​</a></h3><p>参考 RIFT，把未来信息定义成接口而非可视化：未来时间索引、组织/器械状态、置信区间、生成时刻、有效期、依赖的观测版本。视频可以作为审计输出，控制器读取的是有界、可版本化的 latent/结构化状态。</p><p><strong>最小实验与完成标准：</strong> 在网络延迟、丢帧和观测陈旧注入下，对比 current-only、视频 rollout、single-pass future representation；同时报告任务成功、P95/P99 action latency、future age、错误一致性和安全 guard 触发率。任何方法不能只凭平均成功率胜出。</p><h3 id="_3-把机器人-rl-限制成-安全管道内的残差学习" tabindex="-1">3. 把机器人 RL 限制成“安全管道内的残差学习” <a class="header-anchor" href="#_3-把机器人-rl-限制成-安全管道内的残差学习" aria-label="Permalink to &quot;3. 把机器人 RL 限制成“安全管道内的残差学习”&quot;">​</a></h3><p>先用专家示教/传统控制器建立可执行基线，冻结大部分表示，只让 residual policy 学任务相关纠偏；在仿真→台架→离体组织分阶段扩大 reset 分布。每次 safety guard 改写动作，都记录 <code>base_action / residual_action / projected_action / triggered_rule / outcome</code>。</p><p><strong>完成标准：</strong> residual 关闭时系统仍可安全运行；开启后高风险 violation 不增加；超出示教支持、critic 分歧过大或 guard 连续触发时自动退出到基线/人工控制。不得以“在线学习”名义在患者上探索。</p><h3 id="_4-把患者侧约束表达成相对坐标与显式规则" tabindex="-1">4. 把患者侧约束表达成相对坐标与显式规则 <a class="header-anchor" href="#_4-把患者侧约束表达成相对坐标与显式规则" aria-label="Permalink to &quot;4. 把患者侧约束表达成相对坐标与显式规则&quot;">​</a></h3><p>借鉴机器人超声，把器械目标从绝对位姿转换为组织表面、RCM、视线、禁区和接触状态的相对约束；高层模型更新目标，患者侧模型持续闭合误差。</p><p><strong>完成标准：</strong> 在相机移动、组织位移、网络中断和模型输出冻结条件下，患者侧仍满足 RCM/力/速度/工作空间边界；每条规则都有触发证据、动作投影结果和回放测试。</p><h3 id="_5-ai-native-工作流同样采用多时间尺度自治" tabindex="-1">5. AI Native 工作流同样采用多时间尺度自治 <a class="header-anchor" href="#_5-ai-native-工作流同样采用多时间尺度自治" aria-label="Permalink to &quot;5. AI Native 工作流同样采用多时间尺度自治&quot;">​</a></h3><p>长时间规划 Agent 负责目标和方案；任务 Agent 负责可逆实现；命令口 guard 负责路径、权限、远端领先、测试和部署 receipt。不要让一个长上下文 Agent 同时承担策略、执行和自我验收。</p><p><strong>完成标准：</strong> commit/push/deploy 等动作只由独立 receipt 建立事实；远端领先、工作区有用户改动或验证超时都触发确定性停止。今天晨报遇到的“本地落后远端且索引有重叠修改”正是这种边界应阻止自动发布的例子。</p><hr><h2 id="值得继续跟踪的问题" tabindex="-1">值得继续跟踪的问题 <a class="header-anchor" href="#值得继续跟踪的问题" aria-label="Permalink to &quot;值得继续跟踪的问题&quot;">​</a></h2><ol><li>G0.5 的 prompt-level 行为 steering 在大规模、对抗性措辞和跨 embodiment 条件下是否仍稳定？</li><li>当 reasoning 与 action 共享 decoder 和目标时，怎样证明语言错误不会直接放大为危险动作？</li><li>RIFT 的 single-pass future cache 在真实机器人、低算力边缘设备和非 WAM backbone 上还能保留多少收益？</li><li>future estimator 一致但同时错误时，什么外部物理残差能更早发现问题？</li><li>MiDAS 的“一条示教”在缝合、牵拉、打结等多模态精细接触任务中，究竟需要多少 distinct behavior modes？</li><li>如何把 MiDAS 的自动 reset、稀疏奖励和 success buffer 替换成适合手术的离线/安全数据闭环？</li><li>表面相对控制如何融合接触力、呼吸形变、遮挡和 RGB-D 缺失，并给出可验证的误差上界？</li><li>Koopman 触觉稳定性分析在可变网络时延、量化、丢包和双边遥操作下是否仍比 passivity 方法更实用？</li><li>safety guard 频繁投影动作时，怎样判断是策略需要重新训练、传感器失效，还是规则过紧？</li><li>多时间尺度系统的事故回放，能否从慢环目标一路重建到患者侧实际执行的每个动作？</li></ol><hr><h2 id="来源链接" tabindex="-1">来源链接 <a class="header-anchor" href="#来源链接" aria-label="Permalink to &quot;来源链接&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2608.11739" target="_blank" rel="noreferrer">arXiv：G0.5——统一自回归机器人推理与动作</a></li><li><a href="https://arxiv.org/html/2608.11739v1" target="_blank" rel="noreferrer">arXiv HTML：G0.5 架构、训练、实验与定性边界</a></li><li><a href="https://opengalaxea.github.io/G05/" target="_blank" rel="noreferrer">G0.5 作者项目页</a></li><li><a href="https://arxiv.org/abs/2608.11521" target="_blank" rel="noreferrer">arXiv：RIFT——保留未来表征、移除视频 rollout</a></li><li><a href="https://arxiv.org/html/2608.11521v2" target="_blank" rel="noreferrer">arXiv HTML：RIFT future-cache 干预、延迟、OOD 与局限</a></li><li><a href="https://arxiv.org/abs/2608.11363" target="_blank" rel="noreferrer">arXiv：MiDAS——最小数据机器人策略适配</a></li><li><a href="https://arxiv.org/html/2608.11363v1" target="_blank" rel="noreferrer">arXiv HTML：MiDAS 单示教、真实双臂结果、reset curriculum 与边界</a></li><li><a href="https://minimal-data-adaptation.github.io/" target="_blank" rel="noreferrer">MiDAS 作者项目页</a></li><li><a href="https://arxiv.org/abs/2608.11409" target="_blank" rel="noreferrer">arXiv：机器人超声任意倾角跟踪</a></li><li><a href="https://arxiv.org/abs/2608.11461" target="_blank" rel="noreferrer">arXiv：非线性触觉虚拟环境的 Koopman 表示与稳定性分析</a></li><li><a href="https://arxiv.org/abs/2608.11451" target="_blank" rel="noreferrer">arXiv：命令接口神经符号 safety guard</a></li><li><a href="https://arxiv.org/list/cs.AI/new" target="_blank" rel="noreferrer">arXiv：cs.AI 最新列表</a></li><li><a href="https://arxiv.org/list/cs.RO/new" target="_blank" rel="noreferrer">arXiv：cs.RO 最新列表</a></li><li><a href="https://www.fda.gov/medical-devices/surgery-devices/computer-assisted-surgical-systems" target="_blank" rel="noreferrer">FDA：Computer-Assisted Surgical Systems</a></li><li><a href="https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/denovo.cfm" target="_blank" rel="noreferrer">FDA：De Novo 数据库</a></li><li><a href="https://www.jnj.com/media-center/press-releases/johnson-johnson-receives-fda-market-authorization-in-the-u-s-for-its-ottava-robotic-surgical-system" target="_blank" rel="noreferrer">Johnson &amp; Johnson：OTTAVA De Novo 官方公告（2026-07-22，窗口外基线）</a></li><li><a href="https://www.intuitive.com/en-us/about-us/newsroom" target="_blank" rel="noreferrer">Intuitive：官方 Newsroom</a></li></ul><hr><p><em>事实以链接所示原始来源为准；“作者结果”表示论文作者报告的数据，并非独立复现；“来源观点”表示论文作者的解释；“推断”是结合 Nathan 当前 AI Native、远程手术和机器人强化学习方向给出的工程判断。预印本、模拟器、通用双臂台架、机器人超声和自动驾驶 guard，在真实软组织、远程链路、完整风险管理与临床验证前，均不应外推为手术安全性或有效性结论。</em></p>',67)])])}const u=a(i,[["render",n]]);export{d as __pageData,u as default};
